/// A note-on event emitted by the UI when a key is played. `note` is a
/// semitone offset (0 = C), `velocity` is normalized 0..1. The audio engine
/// subscribes via [`run_demo_with_note_sink`]; the render path never blocks on
/// it (fire-and-forget), so animation load cannot affect sound.
#[derive(Clone, Copy, Debug)]
#[allow(dead_code)] // fields are read by the audio engine's sink (task-4)
pub struct NoteEvent {
    pub note: u8,
    pub velocity: f32,
    pub source: SourceId,
    /// Arrival timestamp (hardware MIDI latency measurement, task-23).
    pub created: std::time::Instant,
}

/// Hardware MIDI → engine from the midir thread (see `DemoApp::hw_direct`).
/// Same mapping as the note sink: velocity scaled by the Keys VEL knob
/// (published lock-free by the UI), velocity 0 = NoteOff.
/// Hardware MIDI devices as the MIDI thread sees them: (port name, plugged
/// in) per device index = `SourceId::Hardware(index)`. An unplugged device
/// keeps its index, so rig bindings and learned CCs survive a re-plug.
#[derive(Default)]
struct HwMidi {
    devices: Mutex<Vec<(String, bool)>>,
    rev: std::sync::atomic::AtomicU64,
}

/// The MIDI thread: connects every hardware input, rescans every
/// `HW_RESCAN_SECS` for hot-plugged devices, and owns the connections, so
/// sound never depends on UI frames (rule 31). Ends with the app.
fn spawn_hw_midi(
    hw: Arc<HwMidi>,
    q: Arc<Mutex<VecDeque<(NoteEvent, bool)>>>,
    cc_q: Arc<Mutex<VecDeque<(SourceId, u8, u8, u8)>>>,
    direct: Arc<HwDirect>,
) {
    let spawned = std::thread::Builder::new().name("kabelsalat-midi".into()).spawn(move || {
        let mut conns: Vec<Option<midir::MidiInputConnection<()>>> = Vec::new();
        while Arc::strong_count(&hw) > 1 {
            rescan_hw_midi(&hw, &mut conns, &q, &cc_q, &direct);
            std::thread::sleep(std::time::Duration::from_secs_f32(HW_RESCAN_SECS));
        }
    });
    if let Err(e) = spawned {
        eprintln!("midi: hot-plug thread failed to start: {e}");
    }
}

/// A MIDI port name without ALSA's trailing "client:port" numbers
/// ("FM-1:FM-1 MIDI 1 24:0" → "FM-1:FM-1 MIDI 1"): stable across re-plugs.
pub(crate) fn midi_port_key(name: &str) -> &str {
    match name.rsplit_once(' ') {
        Some((head, tail)) if tail.split_once(':').is_some_and(|(c, p)| {
            !c.is_empty() && !p.is_empty() && c.bytes().all(|b| b.is_ascii_digit()) && p.bytes().all(|b| b.is_ascii_digit())
        }) => head,
        _ => name,
    }
}

/// A hardware MIDI port as people read it: the device, and the port when
/// the device has several ("ESI MIDIMATE eX:ESI MIDIMATE eX MIDI 2 24:1" →
/// "ESI MIDIMATE eX" + "Port 2"). ALSA repeats the client name in the port
/// name and appends "client:port" numbers that change on a re-plug.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct MidiPortName { pub device: String, pub port: String }

pub(crate) fn midi_port_name(raw: &str) -> MidiPortName {
    let key = midi_port_key(raw);
    let Some((client, port)) = key.split_once(':') else {
        return MidiPortName { device: key.trim().to_string(), port: String::new() };
    };
    let port = port.strip_prefix(client).unwrap_or(port).trim();
    let port = match port.strip_prefix("MIDI ") {
        Some(n) if !n.is_empty() && n.bytes().all(|b| b.is_ascii_digit()) => format!("Port {n}"),
        _ => port.to_string(),
    };
    MidiPortName { device: client.trim().to_string(), port }
}

/// Which known device index a port belongs to (#16). `Err(())` = already
/// connected (live under this exact name), `Ok(None)` = a new device.
/// A re-plug can get another ALSA client number: an OFFLINE device with the
/// same name minus that number is the same keyboard, so it keeps its index
/// (and with it its rig binding and matrix row).
fn match_midi_device(devices: &[(String, bool)], name: &str) -> Result<Option<usize>, ()> {
    if let Some(i) = devices.iter().position(|(n, _)| n == name) {
        return if devices[i].1 { Err(()) } else { Ok(Some(i)) };
    }
    let key = midi_port_key(name);
    Ok(devices.iter().position(|(n, live)| !*live && midi_port_key(n) == key))
}

/// Is ALSA port `name` ("…  28:0") still subscribed by one of our
/// `kabelsalat-hw` clients, per the text of /proc/asound/seq/clients?
/// None = cannot tell (no "client:port" suffix, port not listed). A USB
/// re-plug that brings the device back under the SAME name drops the
/// subscription silently; the name alone said "still connected" and the
/// keyboard stayed dead.
fn alsa_port_subscribed(seq_clients: &str, name: &str) -> Option<bool> {
    let (c, p) = name.rsplit_once(' ')?.1.split_once(':')?;
    let (c, p): (u32, u32) = (c.parse().ok()?, p.parse().ok()?);
    let mut ours = Vec::new();
    let mut client: Option<u32> = None;
    for line in seq_clients.lines() {
        if let Some(rest) = line.strip_prefix("Client") {
            let n = rest.trim_start().split(|ch: char| !ch.is_ascii_digit()).next().and_then(|x| x.parse().ok());
            if let Some(n) = n { if line.contains("\"kabelsalat-hw\"") { ours.push(n); } }
            client = n;
        }
    }
    let mut in_port = false;
    let mut found = false;
    for line in seq_clients.lines() {
        if let Some(rest) = line.strip_prefix("Client") {
            let n: Option<u32> = rest.trim_start().split(|ch: char| !ch.is_ascii_digit()).next().and_then(|x| x.parse().ok());
            client = n;
            in_port = false;
            continue;
        }
        let t = line.trim_start();
        if let Some(rest) = t.strip_prefix("Port") {
            let n: Option<u32> = rest.trim_start().split(|ch: char| !ch.is_ascii_digit()).next().and_then(|x| x.parse().ok());
            in_port = client == Some(c) && n == Some(p);
            if in_port { found = true; }
            continue;
        }
        if in_port {
            if let Some(targets) = t.strip_prefix("Connecting To:") {
                let to_us = targets.split(',').any(|x| {
                    x.trim().split(':').next().and_then(|n| n.trim().parse::<u32>().ok()).is_some_and(|n| ours.contains(&n))
                });
                if to_us { return Some(true); }
            }
        }
    }
    found.then_some(false)
}

/// A MIDI input port that is a device: not ours, not ALSA's own. The
/// kernel's Midi Through port counts with KABELSALAT_MIDI_THROUGH=1, a
/// hardware-path self-test feed (aseqsend -p 14:0).
pub(crate) fn is_hw_midi_port(name: &str) -> bool {
    let through_ok = std::env::var("KABELSALAT_MIDI_THROUGH").is_ok_and(|v| !v.is_empty() && v != "0");
    !(name.contains("kabelsalat") || (name.contains("Midi Through") && !through_ok) || name == "System" || name == "Announce")
}

fn rescan_hw_midi(
    hw: &HwMidi,
    conns: &mut Vec<Option<midir::MidiInputConnection<()>>>,
    q: &Arc<Mutex<VecDeque<(NoteEvent, bool)>>>,
    cc_q: &Arc<Mutex<VecDeque<(SourceId, u8, u8, u8)>>>,
    direct: &Arc<HwDirect>,
) {
    let Ok(probe) = midir::MidiInput::new("kabelsalat-probe") else { return };
    let ports: Vec<(String, midir::MidiInputPort)> = probe.ports().into_iter()
        .map(|p| (probe.port_name(&p).unwrap_or_default(), p))
        .filter(|(name, _)| is_hw_midi_port(name))
        .collect();
    // Decide under the lock, connect/close outside it: the UI frame reads
    // the same list and must never wait for an ALSA port to open.
    let (unplugged, to_connect) = {
        let Ok(mut devices) = hw.devices.lock() else { return };
        let mut unplugged = Vec::new();
        // A device re-plugged under the same name lost our subscription:
        // treat it as unplugged so this pass reconnects it.
        let seq = std::fs::read_to_string("/proc/asound/seq/clients").unwrap_or_default();
        for (i, (name, live)) in devices.iter_mut().enumerate() {
            let stale = *live && alsa_port_subscribed(&seq, name) == Some(false);
            if stale { eprintln!("midi: {name} lost its subscription (re-plugged?) — reconnecting"); }
            if *live && (stale || !ports.iter().any(|(n, _)| n == name)) {
                *live = false;
                unplugged.push(i);
            }
        }
        let mut to_connect = Vec::new();
        for (name, port) in &ports {
            let dev = match match_midi_device(&devices, name) {
                Err(()) => continue,
                Ok(Some(i)) => {
                    devices[i].0 = name.clone(); // the new client number
                    i
                }
                Ok(None) if devices.len() >= crate::engine::MAX_HW_DEVICES as usize => {
                    // The engine routes Hardware(0..16) only: a 17th id would be mute.
                    eprintln!("midi: {name} ignored — {} hardware devices is the limit", crate::engine::MAX_HW_DEVICES);
                    continue;
                }
                Ok(None) => {
                    devices.push((name.clone(), false));
                    devices.len() - 1
                }
            };
            to_connect.push((dev, name.clone(), port.clone()));
        }
        (unplugged, to_connect)
    };
    let mut changed = !unplugged.is_empty();
    for i in unplugged {
        if let Some(c) = conns.get_mut(i).and_then(Option::take) { c.close(); }
    }
    for (dev, name, port) in to_connect {
        if conns.len() <= dev { conns.resize_with(dev + 1, || None); }
        conns[dev] = connect_hw_input(&port, dev as u32, q, cc_q, direct);
        if conns[dev].is_some() {
            if let Ok(mut devices) = hw.devices.lock() {
                if let Some(d) = devices.get_mut(dev) { d.1 = true; }
            }
            eprintln!("midi: connected {name}");
            changed = true;
        }
    }
    if changed {
        hw.rev.fetch_add(1, std::sync::atomic::Ordering::Release);
    }
}

/// A hardware pitch bend or aftertouch as the engine command it becomes.
/// Wind controllers send breath as channel pressure, which is 2 bytes on
/// the wire.
fn hw_expression(dev: u32, msg: &[u8]) -> Option<Command> {
    let (source, channel) = (SourceId::Hardware(dev), *msg.first()? & 0x0F);
    match msg.first()? & 0xF0 {
        0xD0 => Some(Command::Pressure { source, channel, note: None, value: *msg.get(1)? & 0x7F }),
        0xA0 => Some(Command::Pressure { source, channel, note: Some(*msg.get(1)? & 0x7F), value: *msg.get(2)? & 0x7F }),
        0xE0 => {
            let value = ((*msg.get(2)? as i16 & 0x7F) << 7 | (*msg.get(1)? as i16 & 0x7F)) - 8192;
            Some(Command::PitchBend { source, channel, value })
        }
        _ => None,
    }
}

/// Open one hardware input. Events sound from the MIDI thread (rule 31) and
/// queue for the UI animation.
fn connect_hw_input(
    port: &midir::MidiInputPort,
    dev: u32,
    q: &Arc<Mutex<VecDeque<(NoteEvent, bool)>>>,
    cc_q: &Arc<Mutex<VecDeque<(SourceId, u8, u8, u8)>>>,
    direct: &Arc<HwDirect>,
) -> Option<midir::MidiInputConnection<()>> {
    let mi = midir::MidiInput::new("kabelsalat-hw").ok()?;
    let (q, cc_q, direct) = (q.clone(), cc_q.clone(), direct.clone());
    mi.connect(
        port,
        "kabelsalat-hw",
        move |_stamp, msg: &[u8], _| {
            if let Some(cmd) = hw_expression(dev, msg) {
                let _ = direct.send_now(cmd, std::time::Instant::now());
                return;
            }
            if msg.len() >= 3 {
                let st = msg[0] & 0xF0;
                if st == 0x90 || st == 0x80 {
                    let vel = if st == 0x90 { msg[2] as f32 / 127.0 } else { 0.0 };
                    let ev = NoteEvent { note: msg[1], velocity: vel, source: SourceId::Hardware(dev), created: std::time::Instant::now() };
                    let sounded = direct.send(&ev);
                    if let Ok(mut q) = q.lock() {
                        q.push_back((ev, sounded));
                        while q.len() > 256 {
                            q.pop_front();
                        }
                    }
                } else if st == 0xB0 {
                    let ch = msg[0] & 0x0F;
                    let cc = msg[1] & 0x7F;
                    let val = msg[2] & 0x7F;
                    let src = SourceId::Hardware(dev);
                    let _ = direct.send_cc(src, ch, cc, val, std::time::Instant::now());
                    if let Ok(mut cq) = cc_q.lock() {
                        cq.push_back((src, ch, cc, val));
                        while cq.len() > 256 {
                            cq.pop_front();
                        }
                    }
                }
            }
        },
        (),
    ).ok()
}

struct HwDirect {
    bus: Mutex<Option<Arc<Mutex<CommandBus>>>>,
    /// Keys VEL knob as f32 bits (starts at the knob's 0.8 default).
    keys_vel: std::sync::atomic::AtomicU32,
}

impl Default for HwDirect {
    fn default() -> Self {
        Self { bus: Mutex::new(None), keys_vel: std::sync::atomic::AtomicU32::new(0.8f32.to_bits()) }
    }
}

impl HwDirect {
    fn set_keys_vel(&self, v: f32) { self.keys_vel.store(v.to_bits(), Ordering::Relaxed); }

    /// Send one hardware note to the engine. False when no engine is attached
    /// (the UI frame then sounds it through the note sink).
    fn send(&self, ev: &NoteEvent) -> bool {
        let Ok(guard) = self.bus.lock() else { return false };
        let Some(bus) = guard.as_ref() else { return false };
        let kv = f32::from_bits(self.keys_vel.load(Ordering::Relaxed));
        let cmd = if ev.velocity > 0.0 {
            Command::NoteOn { note: ev.note, velocity: (ev.velocity * (0.35 + kv * 0.65)).clamp(0.0, 1.0), source: ev.source, channel: 0 }
        } else {
            Command::NoteOff { note: ev.note, source: ev.source, channel: 0 }
        };
        let ok = bus.lock().map(|mut b| b.send(cmd)).unwrap_or(false);
        crate::bridge::record_midi_latency(ev.created.elapsed().as_micros() as u32);
        ok
    }

    /// Send one hardware CC straight to the engine from the midir thread.
    fn send_cc(&self, source: SourceId, channel: u8, cc: u8, value: u8, created: std::time::Instant) -> bool {
        let Ok(guard) = self.bus.lock() else { return false };
        let Some(bus) = guard.as_ref() else { return false };
        let cmd = Command::Cc {
            source,
            channel: channel & 0x0F,
            cc: cc & 0x7F,
            value: value & 0x7F,
        };
        let ok = bus.lock().map(|mut b| b.send(cmd)).unwrap_or(false);
        crate::bridge::record_midi_latency(created.elapsed().as_micros() as u32);
        ok
    }

    /// Send one hardware channel message (pitch bend, aftertouch) straight
    /// to the engine from the midir thread, like [`Self::send_cc`].
    fn send_now(&self, cmd: Command, created: std::time::Instant) -> bool {
        let Ok(guard) = self.bus.lock() else { return false };
        let Some(bus) = guard.as_ref() else { return false };
        let ok = bus.lock().map(|mut b| b.send(cmd)).unwrap_or(false);
        crate::bridge::record_midi_latency(created.elapsed().as_micros() as u32);
        ok
    }
}

/// Sink for [`NoteEvent`]s. `Send` so the engine can move it to its own thread.
pub type NoteSink = Box<dyn FnMut(NoteEvent) + Send>;

// ---------------------------------------------------------------------------
// Model
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum PortKind { Midi, Audio }

#[derive(Clone, Copy, PartialEq, Eq)]
enum Dir { In, Out }

impl PortKind {
    fn color(self) -> Color32 {
        match self { PortKind::Midi => YELLOW, PortKind::Audio => theme::AUDIO_CREAM }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Side { Front, Back }

const KNOB_GLIDE_SECS: f32 = 0.20;
const KNOB_DRAG_SENSITIVITY: f32 = 0.006;
/// Holding Shift while dragging a knob slows travel by 10x for fine adjustments (#304).
const KNOB_FINE_FACTOR: f32 = 0.1;
const CABLE_DRAW_IN_SECS: f32 = 0.28;
const UNIT_FADE_SECS: f32 = 0.24;
const AGENT_PULSE_SECS: f32 = 0.38;

struct Knob {
    label: String,
    /// Target/logical value published immediately to the engine (rule 31).
    value: f32,
    /// Visual needle/arc value (equals `value` on drag/load, glides on agent edits).
    display_value: f32,
    glide_from: f32,
    glide_t: f32,
    default: f32,
    /// Engine param id this knob publishes (None = visual-only knob).
    param: Option<u32>,
    /// > 1 = a stepped picker (MODE, RATE, …): the value snaps to this many
    /// evenly spaced positions — on drag, on load, and before publishing.
    steps: u8,
    /// Hidden from the face (still settable/bindable — e.g. AudioIn MON, shown
    /// as a chip instead of a knob). Skipped by draw + face-layout audit.
    hidden: bool,
    /// Last value sent via `Command::SetParam` so `publish_patch` only sends on change
    /// and never fights incoming hardware CCs.
    sent: Option<f32>,
    /// A Surge parameter pinned from the synth editor: the knob drives the
    /// PLUGIN parameter (0..1 mapped onto min..max), sent only on change.
    clap: Option<ClapPin>,
    /// Where the knob comes from: the unit's own table, or a plugin parameter.
    source: KnobSource,
    /// Cached CLAP `value_to_text` readout `(normalized_value, formatted_text)`
    /// refreshed lazily while hovered, dragged, or open in the knob menu (#304).
    cached_text: Option<(f32, String)>,
    label_g: Option<Arc<theme::TrackedLabel>>,
}

/// A knob's origin. Plugin knobs carry the parameter's full name, which
/// agents and CC bindings may use instead of the short face label.
#[derive(Clone, PartialEq)]
enum KnobSource {
    /// From `engine::knob_specs`.
    BuiltIn,
    /// One of the instrument's main controls (`main_controls::resolve`).
    Main(String),
    /// Pinned by hand from the synth editor.
    Pinned(String),
    /// Shown automatically because a MIDI CC binding controls this parameter.
    Midi { name: String, resolved: bool },
}

impl KnobSource {
    fn plugin_name(&self) -> Option<&str> {
        match self {
            KnobSource::BuiltIn => None,
            KnobSource::Main(n) | KnobSource::Pinned(n) | KnobSource::Midi { name: n, .. } => Some(n),
        }
    }
}

impl Knob {
    /// Snap to the knob's steps (a no-op on a continuous knob).
    fn quantize(&self, v: f32) -> f32 {
        if self.steps < 2 {
            return v.clamp(0.0, 1.0);
        }
        let n = (self.steps - 1) as f32;
        (v.clamp(0.0, 1.0) * n).round() / n
    }

    /// The knob's current value as a step index (0-based, for readouts).
    fn step_index(&self) -> usize {
        if self.steps < 2 {
            return 0;
        }
        (self.value * (self.steps - 1) as f32).round().clamp(0.0, (self.steps - 1) as f32) as usize
    }

    fn set_immediate(&mut self, v: f32) {
        let v = self.quantize(v);
        self.value = v;
        self.display_value = v;
        self.glide_from = v;
        self.glide_t = 1.0;
    }

    fn glide_to(&mut self, v: f32, reduce_motion: bool) {
        let v = self.quantize(v);
        self.value = v;
        if reduce_motion || (self.display_value - v).abs() < 1e-4 {
            self.display_value = v;
            self.glide_from = v;
            self.glide_t = 1.0;
        } else {
            self.glide_from = self.display_value;
            self.glide_t = 0.0;
        }
    }

    /// Engine or plugin target this knob controls, if bindable to MIDI CC.
    fn cc_target(&self) -> Option<(u32, crate::matrix::CcTarget)> {
        if let Some(pin) = self.clap {
            Some((pin.id, crate::matrix::CcTarget::PluginParam))
        } else {
            self.param.map(|p| (p, crate::matrix::CcTarget::Knob))
        }
    }
}

#[derive(Clone, Copy)]
struct ClapPin {
    id: u32,
    min: f64,
    max: f64,
    sent: f32,
    /// Until this `ui_time` the plugin's value is not read back: a value on
    /// its way to the audio thread would snap the knob to the old one.
    hold_until: f32,
}

/// Most plugin parameters on one synth face (main controls and pins together).
const MAX_PINS: usize = crate::main_controls::FACE_MAIN_CONTROLS;
/// Width a knob label may use: one knob slot minus a gap to its neighbour.
const KNOB_LABEL_W: f32 = KNOB_PITCH - 6.0;
/// How often plugin knobs follow their plugin (values and renamed controls).
const MAIN_POLL_SECS: f32 = 0.1;
/// How often an Aeolus face re-reads which stops its plugin has drawn (the
/// face's own clicks and sound loads update it at once).
const AEOLUS_POLL_SECS: f32 = 1.0;

/// An Aeolus unit's stop panel: what the plugin has drawn (None until read,
/// or for an organ other than the default one) and the division shown.
#[derive(Clone, Copy, Debug, PartialEq)]
struct AeolusFace {
    drawn: Option<[u32; 4]>,
    division: usize,
    tremulant: [bool; 4],
    couplers: [u8; 4],
}

impl Default for AeolusFace {
    /// Manual I, where the registration a fresh Aeolus starts with sits.
    fn default() -> Self {
        AeolusFace { drawn: None, division: 2, tremulant: [false; 4], couplers: [0; 4] }
    }
}

/// Where an Aeolus face lays out its division tabs and the stops of the
/// division it shows (rack-local).
struct AeolusRects {
    tabs: [Rect; 4],
    stops: Vec<Rect>,
}
/// Readback pause after the UI or a CC moved a plugin knob.
const READBACK_HOLD_SECS: f32 = 0.3;
/// The warm shift an instrument's audio cable carries (the former TONE
/// knob's default × 0.20, §4.10).
const INSTRUMENT_CABLE_WARMTH: f32 = 0.07;

/// A jack on the back panel: direction, port index, x fraction of the unit.
struct Jack {
    dir: Dir,
    port: usize,
    xf: f32,
    label: &'static str,
    label_g: Option<Arc<theme::TrackedLabel>>,
}

/// What a rack unit IS — drives its face, knobs, and layout grouping.
#[derive(Clone)]
enum UnitKind {
    Keys,
    Clap,
    Dsp(crate::control::DspKind),
    Master,
    /// Live audio input (mic/guitar/interface): a source with an audio OUT.
    AudioIn,
    /// Hosted MIDI effect (AUM MIDI strip): MIDI in, MIDI out.
    MidiFx,
    /// The arpeggiator / chord unit (issue #90): one MIDI in, one MIDI out.
    Arp,
}

struct Unit {
    /// Engine node id (control-plane Graph). Unit index ≠ node id in general.
    node_id: u32,
    /// Rig tag from the control-plane node (merge_rigs). The big view shows
    /// one rig at a time; single-graph mode is all-rig-0.
    rig: u8,
    /// LV2 instrument (vs effect) — matrix sink column. Classified in build_rack.
    lv2_inst: bool,
    /// CLAP audio effect (vs instrument) — audio IN + OUT, effect column/insert.
    clap_fx: bool,
    node_kind: UnitKind,
    name: String,
    sub: String,
    ins: [PortKind; 3],
    outs: [PortKind; 3],
    knobs: Vec<Knob>,
    /// Which plugin the main-control knobs were built from (a CLAP voice id,
    /// 0 for an LV2 plugin); None until that plugin's controls are known.
    main_from: Option<u64>,
    jacks: Vec<Jack>,
    led: f32,
    /// The node owns a start/stop transport (`NodeKind::supports_transport`:
    /// metronome today, the file player later) → its face gets a Play/Stop chip.
    transport: bool,
    /// Mirror of the engine's `Node::playing` (GraphPub), never a local guess
    /// while an engine is attached.
    playing: bool,
    /// Keys only: mirror of `Node::split`. Some = TWO MIDI OUT jacks (LOW on
    /// port 0, HIGH on port 1); None = one MIDI OUT. Never a local guess
    /// while an engine is attached (adopted from GraphPub).
    split: Option<u8>,
    /// AudioIn only: mirror of the node's device selection (None = default).
    device: Option<String>,
    /// AudioIn only: which device channels fill the stereo OUT.
    channels: AudioInChannel,
    name_g: Option<Arc<Galley>>,
    sub_g: Option<Arc<theme::TrackedLabel>>,
    /// Unit width the name/subtitle galleys were fitted to (C4 shrink-to-
    /// fit); INFINITY = natural size (rects not laid out yet).
    label_fit_w: f32,
    /// Whether the title galley was fitted with room reserved for the BYPASSED chip.
    bypassed_fit: bool,
    back_g: Option<Arc<theme::TrackedLabel>>,
}

impl Unit {
    /// Index of the knob with this face label. Knob positions shift with
    /// the plugin knobs in front of them, labels do not.
    fn knob_index(&self, label: &str) -> Option<usize> {
        self.knobs.iter().position(|k| k.label == label)
    }
    fn jack_local(&self, unit_rect: Rect, ji: usize) -> Vec2 {
        let j = &self.jacks[ji];
        Vec2::new(unit_rect.left() + unit_rect.width() * j.xf, unit_rect.top() + unit_rect.height() * 0.54)
    }
    fn jack_index(&self, dir: Dir, port: usize) -> Option<usize> {
        self.jacks.iter().position(|j| j.dir == dir && j.port == port)
    }
    fn kind(&self, dir: Dir, port: usize) -> PortKind {
        if dir == Dir::In {
            self.ins.get(port).copied().unwrap_or(PortKind::Audio)
        } else {
            self.outs.get(port).copied().unwrap_or(PortKind::Audio)
        }
    }
}

/// Build a knob. `param` = engine param id it publishes (None = visual-only).
fn knob(label: &'static str, default: f32, param: Option<u32>) -> Knob {
    Knob {
        label: label.to_string(),
        value: default,
        display_value: default,
        glide_from: default,
        glide_t: 1.0,
        default,
        param,
        steps: 0,
        hidden: false,
        sent: None,
        clap: None,
        source: KnobSource::BuiltIn,
        cached_text: None,
        label_g: None,
    }
}

/// Build a stepped knob (a picker: MODE, RATE …): `steps` even positions.
fn stepped_knob(label: &'static str, default: f32, param: Option<u32>, steps: u8) -> Knob {
    let mut k = knob(label, default, param);
    k.steps = steps.max(2);
    k.set_immediate(default);
    k
}

/// A hidden knob (drive-by chip/param, not drawn on the face). Still bindable
/// and persisted; the face renders its state as a chip instead.
fn hidden_knob(label: &'static str, default: f32, param: Option<u32>) -> Knob {
    let mut k = knob(label, default, param);
    k.hidden = true;
    k
}

/// Which plugin moves a main-control knob.
#[derive(Clone, Copy)]
enum MainTarget {
    /// A CLAP parameter, sent through the voice controller.
    Clap,
    /// An LV2 control port, sent as the engine's `SetParam`.
    Lv2,
}

/// A face knob for one main control at the plugin's current `value`.
fn main_knob(c: &crate::main_controls::MainControl, value: f64, target: MainTarget) -> Knob {
    let norm = c.normalized(value);
    Knob {
        label: crate::main_controls::knob_label(&c.name),
        value: norm,
        display_value: norm,
        glide_from: norm,
        glide_t: 1.0,
        default: c.normalized(c.default),
        param: matches!(target, MainTarget::Lv2).then_some(c.id),
        // Plugin parameters keep their own stepping (the plugin rounds);
        // the rack's stepped knobs are the built-in ones (knob_specs).
        steps: 0,
        hidden: false,
        sent: Some(norm),
        clap: matches!(target, MainTarget::Clap)
            .then_some(ClapPin { id: c.id, min: c.min, max: c.max, sent: norm, hold_until: 0.0 }),
        source: KnobSource::Main(c.name.clone()),
        cached_text: None,
        label_g: None,
    }
}

/// Replace a unit's main-control knobs. They lead the knob row; with the
/// hand-pinned and MIDI-controlled ones a face holds up to `MAX_PINS` plugin
/// knobs (MIDI-controlled knobs are never dropped).
fn set_main_knobs(
    u: &mut Unit,
    face: &[crate::main_controls::MainControl],
    target: MainTarget,
    mut value: impl FnMut(&crate::main_controls::MainControl) -> f64,
) {
    u.knobs.retain(|k| !matches!(k.source, KnobSource::Main(_)));
    let kept: Vec<u32> = u
        .knobs
        .iter()
        .filter(|k| k.source != KnobSource::BuiltIn)
        .filter_map(|k| k.clap.map(|pin| pin.id).or(k.param))
        .collect();
    let fresh: Vec<Knob> = face
        .iter()
        .filter(|c| !kept.contains(&c.id))
        .take(MAX_PINS.saturating_sub(kept.len()))
        .map(|c| main_knob(c, value(c), target))
        .collect();
    u.knobs.splice(0..0, fresh);
}

/// Move a unit's CLAP knobs to the values the plugin reports (a loaded
/// patch, an agent's edit, a stepped parameter rounding the knob's value).
fn follow_plugin_values(u: &mut Unit, main: &mut ClapVoiceMain, now: f32, reduce_motion: bool) {
    for k in &mut u.knobs {
        let Some(pin) = k.clap else { continue };
        // An unsent change is the UI's own: publish_pins sends it this frame.
        if now < pin.hold_until || (k.value - pin.sent).abs() > 1e-4 { continue; }
        let Some(plain) = main.param_value(pin.id) else { continue };
        let norm = (((plain - pin.min) / (pin.max - pin.min).max(1e-9)) as f32).clamp(0.0, 1.0);
        if (norm - k.value).abs() > 2e-3 {
            k.glide_to(norm, reduce_motion);
            k.clap = Some(ClapPin { sent: norm, ..pin });
        }
    }
}

/// Keys back-panel jacks: one MIDI OUT unsplit; LOW (port 0) + HIGH
/// (port 1) when split (AUM model: a split keyboard is two MIDI sources).
fn keys_jacks(split: Option<u8>) -> Vec<(Dir, usize, f32, &'static str)> {
    match split {
        None => vec![(Dir::Out, 0, 0.62, "MIDI OUT")],
        Some(_) => vec![(Dir::Out, 0, 0.44, "LOW"), (Dir::Out, 1, 0.80, "HIGH")],
    }
}

/// Put a Keys unit's split state + matching jack set in place. Jack label
/// galleys refill lazily in `ensure_galleys`.
fn set_unit_split(u: &mut Unit, split: Option<u8>) {
    if u.split == split && u.jacks.len() == keys_jacks(split).len() { return; }
    u.split = split;
    u.jacks = keys_jacks(split).into_iter()
        .map(|(dir, port, xf, label)| Jack { dir, port, xf, label, label_g: None })
        .collect();
}

/// Value of the knob bound to `param`, or `default` if the unit has no such knob.
fn knob_val(u: &Unit, param: u32, default: f32) -> f32 {
    // The unit's own knobs only: an LV2 control port shares the id space.
    u.knobs.iter().find(|k| k.source == KnobSource::BuiltIn && k.param == Some(param)).map(|k| k.value).unwrap_or(default)
}

/// Visual breathing factor for audio leaving a unit (the engine does the real
/// audio; this only drives the cable width breathing). Clap → LEVEL, Delay →
/// MIX, other DSP → its first knob, everything else → 1.
fn unit_out_gain(u: &Unit) -> f32 {
    match &u.node_kind {
        UnitKind::Clap if !u.clap_fx => 0.25 + knob_val(u, P_LEVEL, 0.85) * 0.75,
        UnitKind::Clap => 1.0,
        UnitKind::Dsp(DspKind::Delay) => 0.15 + knob_val(u, P_MIX, 0.5) * 0.85,
        UnitKind::Dsp(_) => 0.15 + knob_val(u, 0, 0.5) * 0.85,
        _ => 1.0,
    }
}

/// Pulse-speed factor for cables leaving a unit (Delay TIME slows/quickens).
fn unit_time_mul(u: &Unit) -> f32 {
    match &u.node_kind {
        UnitKind::Dsp(DspKind::Delay) => 0.55 + knob_val(u, P_TIME, 0.4) * 1.3,
        _ => 1.0,
    }
}

/// One row of the hot-wire MIDI matrix: a MIDI source that can
/// feed any instrument rig. `Keys` = the computer keyboard (on-screen clicks
/// and laptop typing are ONE source); `HwAll` = any hardware device (omni).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum MatrixRow { Keys, HwAll, HwDev(u32) }

/// A matrix source row as drawn: `port` is set only when its device has
/// several ports, and `continues` marks a further port of the device above.
#[derive(Clone, Debug)]
struct MatrixSource { row: MatrixRow, name: String, port: Option<String>, live: bool, continues: bool, led: f32 }

impl MatrixRow {
    /// The concrete source a row edits (HwAll is an aggregate — no single rule).
    fn source(self) -> Option<SourceId> {
        match self {
            MatrixRow::Keys => Some(SourceId::Keys),
            MatrixRow::HwAll => None,
            MatrixRow::HwDev(d) => Some(SourceId::Hardware(d)),
        }
    }
    fn label(self) -> String {
        match self {
            MatrixRow::Keys => "Keyboard".into(),
            MatrixRow::HwAll => "HW all".into(),
            MatrixRow::HwDev(d) => format!("HW {d}"),
        }
    }
}

/// UI-side mirror of one matrix rule's editable fields (Command::MatrixRule + MatrixCcMap).
/// The engine owns the truth; this drives the editor + cell indicators.
#[derive(Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
struct RuleEdit {
    channel: Option<u8>,
    transpose: i8,
    key_lo: u8,
    key_hi: u8,
    vel_lo: u8,
    vel_hi: u8,
    enabled: bool,
    cc_map: Vec<crate::matrix::CcMapping>,
    /// The engine rule exists only for CC bindings (no notes routed).
    #[serde(default)]
    cc_only: bool,
}

/// One shaped matrix route as a session stores it (`Session::matrix`).
#[derive(serde::Serialize, serde::Deserialize)]
struct SavedRule {
    source: SourceId,
    dest: u32,
    #[serde(flatten)]
    edit: RuleEdit,
}

impl SavedRule {
    fn hw(&self) -> Option<u32> {
        match self.source { SourceId::Hardware(d) => Some(d), _ => None }
    }

    /// A hardware device switched off for `dest`, and nothing else.
    fn hw_off(&self) -> bool {
        self.hw().is_some() && !self.edit.enabled && RuleEdit { enabled: true, ..self.edit.clone() }.is_default()
    }
}

/// `s` moved onto `graph`, every node id mapped by `remap` (None drops it):
/// knobs, plugin states, matrix routes and mixer strips follow their node.
/// Mark every plugin a starter template needs as installed, for tests and
/// shots: a bundle dir per catalog entry under a private plugin root.
#[cfg(test)]
fn template_plugins_installed(app: &mut DemoApp) {
    let root = std::env::temp_dir().join(format!("ksalat-tpl-plugins-{}", std::process::id()));
    for t in Template::ALL {
        for id in t.plugins() {
            let _ = std::fs::create_dir_all(root.join(crate::catalog::find(id).unwrap().bundles[0]));
        }
    }
    app.catalog_roots = Some(vec![root]);
}

/// A starter template's hotkey: F5–F7, then the same keys with Shift.
fn template_key(t: Template) -> (Key, bool) {
    match t {
        Template::CathedralOrgan => (Key::F5, false),
        Template::JazzOrgan => (Key::F6, false),
        Template::RockOrgan => (Key::F7, false),
        Template::GuitarRig => (Key::F5, true),
        Template::AmbientPad => (Key::F6, true),
        Template::SynthLead => (Key::F7, true),
    }
}

/// [`template_key`] as the list prints it ("F5", "Shift+F6").
fn template_key_hint(t: Template) -> String {
    let (key, shift) = template_key(t);
    format!("{}{}", if shift { "Shift+" } else { "" }, key.name())
}

/// Every template id, for the agent tools' "use …" hints.
fn template_names() -> String {
    Template::ALL.iter().map(|t| t.id()).collect::<Vec<_>>().join(", ")
}

fn remap_session(
    s: &crate::session::Session,
    graph: Graph,
    remap: impl Fn(u32) -> Option<u32>,
) -> crate::session::Session {
    let mut ns = crate::session::Session::new(s.name.clone(), graph);
    ns.rig_names = s.rig_names.clone(); // names follow their rig (#33)
    ns.master_target = s.master_target; // session-level, no node ids (#12)
    ns.master_mute = s.master_mute;
    ns.rig_types = s.rig_types.clone(); // marks follow their rig like names (#198)
    ns.time_sig = s.time_sig; // session-level too (#87)
    ns.rig_devices = s.rig_devices.clone(); // and devices (#227)
    ns.set_hw_ports(s.hw_ports().clone());
    for p in s.params() {
        if let Some(nid) = remap(p.node) { ns.set_param(nid, p.param, p.value); }
    }
    for st in s.plugin_states() {
        if let Some(nid) = remap(st.node) { ns.set_plugin_state(nid, st.plugin_id.clone(), st.data.clone()); }
    }
    let rules: Vec<SavedRule> = s.matrix()
        .and_then(|v| serde_json::from_value(v.clone()).ok())
        .unwrap_or_default();
    let rules: Vec<SavedRule> = rules.into_iter()
        .filter_map(|mut r| { r.dest = remap(r.dest)?; Some(r) })
        .collect();
    if !rules.is_empty() {
        ns.set_matrix(serde_json::to_value(&rules).ok());
    }
    // Mixer strips (#72–77) and their display order follow their node.
    for st in s.strips() {
        if let Some(node) = remap(st.node) { ns.set_strip(crate::session::StripSaved { node, ..*st }); }
    }
    let order: Vec<u32> = s.strip_order().iter().filter_map(|n| remap(*n)).collect();
    if !order.is_empty() { ns.set_strip_order(order); }
    for (&old, label) in s.strip_knobs() {
        if let Some(node) = remap(old) { ns.set_strip_knob(node, label.clone()); }
    }
    // Each synth's input selection (#124) follows its node.
    for m in s.midi_sources() {
        if let Some(node) = remap(m.node) { ns.set_midi_sources(crate::session::MidiSources { node, ..m.clone() }); }
    }
    // Sends (issue #5) follow their bus and their source: a node by its id, a
    // rig by where its nodes went (a deleted rig takes its sends along).
    let rig_of = |old: u8| -> Option<u8> {
        let n = s.graph.nodes.iter().find(|n| n.rig == old)?;
        ns.graph.node(remap(n.id)?).map(|n| n.rig)
    };
    let sends: Vec<AuxSend> = s.sends().iter().filter_map(|x| {
        let from = match x.from {
            SendSource::Rig(r) => SendSource::Rig(rig_of(r)?),
            SendSource::Node(n) => SendSource::Node(remap(n)?),
        };
        Some(AuxSend { from, bus: remap(x.bus)?, ..*x })
    }).collect();
    // Bus outputs (#147) follow their rig or their aux bus the same way.
    let outs: Vec<BusOut> = s.bus_outs().iter().filter_map(|o| {
        let bus = match o.bus {
            SendSource::Rig(r) => SendSource::Rig(rig_of(r)?),
            SendSource::Node(n) => SendSource::Node(remap(n)?),
        };
        Some(BusOut { bus, ..*o })
    }).collect();
    let setlist = s.setlist.remap(&rig_of, &remap);
    ns.set_sends(sends);
    ns.set_bus_outs(outs);
    // Setlist (#204): rig indices and stored part knobs follow the remap (rule 44).
    ns.setlist = setlist;
    ns
}

/// The hardware device indices a session's routing depends on (#227): a
/// rig's device, a device with a route or binding of its own, and every
/// device an instrument still hears while others are switched off for it
/// (an LV2 instrument bound to one device has rules only for the others).
fn hw_indices_in_use(rules: &[SavedRule], rig_devices: &[Option<u32>]) -> std::collections::BTreeSet<u32> {
    let mut used: std::collections::BTreeSet<u32> = rig_devices.iter().flatten().copied().collect();
    used.extend(rules.iter().filter(|r| !r.hw_off()).filter_map(SavedRule::hw));
    for muted in rules.iter().filter(|r| r.hw_off()) {
        let off: Vec<u32> = rules.iter().filter(|r| r.dest == muted.dest && r.hw_off()).filter_map(SavedRule::hw).collect();
        used.extend((0..crate::engine::MAX_HW_DEVICES).filter(|d| !off.contains(d)));
    }
    used
}

/// `s` with every hardware device index it holds (matrix rule sources, rig
/// devices, binding levels) moved through `map` (#227). What is left is in this run's
/// indices, so its table of port names goes.
fn map_session_hw(s: &mut crate::session::Session, map: &crate::session::HwIndexMap) {
    let rules: Option<Vec<SavedRule>> = s.matrix().and_then(|v| serde_json::from_value(v.clone()).ok());
    if let Some(mut rules) = rules {
        for r in &mut rules {
            if let SourceId::Hardware(d) = &mut r.source { *d = map.get(*d); }
        }
        // With the device list full, a named device went past it, and the
        // device left over is one the session never knew: off for every
        // instrument some devices are switched off for, like any new one.
        let muted: std::collections::BTreeSet<u32> = rules.iter().filter(|r| r.hw_off()).map(|r| r.dest).collect();
        for dest in muted {
            for d in map.unclaimed() {
                rules.push(SavedRule { source: SourceId::Hardware(d), dest, edit: RuleEdit { enabled: false, ..RuleEdit::default() } });
            }
        }
        s.set_matrix(serde_json::to_value(&rules).ok());
    }
    for d in s.rig_devices.iter_mut().flatten() { *d = map.get(*d); }
    // A pinned binding's level (#273) names its controller's device too.
    for p in &mut s.setlist.levels.bindings {
        if let SourceId::Hardware(d) = &mut p.of.source { *d = map.get(*d); }
    }
    s.set_hw_ports(Default::default());
}

/// A multi-rig session in the id layout the engine's LoadRigs produces
/// (split → merge). Gaps left by removed or added nodes shift a later rig's
/// ids there, so everything keyed on node ids is remapped first.
/// Rig marks without the unmarked tail: empty while no rig is marked, so a
/// session that marks nothing says nothing (#198).
fn trimmed_marks(mut marks: Vec<Option<crate::keyboard::KeyboardType>>) -> Vec<Option<crate::keyboard::KeyboardType>> {
    while marks.last() == Some(&None) { marks.pop(); }
    marks
}

fn canonical_rig_session(s: &crate::session::Session) -> crate::session::Session {
    if s.graph.nodes.iter().all(|n| n.rig == 0) {
        return s.clone();
    }
    let (graphs, old_bases) = crate::control::split_rigs(&s.graph);
    let rigs: Vec<crate::control::Rig> = graphs.into_iter()
        .map(|g| crate::control::Rig::new(String::new(), g, None))
        .collect();
    let new_bases = crate::control::rig_bases(&rigs);
    let merged = crate::control::merge_rigs(&rigs);
    remap_session(s, merged, |old| {
        let rig = s.graph.node(old)?.rig as usize;
        Some(new_bases[rig] + (old - old_bases[rig]))
    })
}

impl Default for RuleEdit {
    fn default() -> Self {
        Self {
            channel: None,
            transpose: 0,
            key_lo: 0,
            key_hi: 127,
            vel_lo: 0,
            vel_hi: 127,
            enabled: true,
            cc_map: Vec::new(),
            cc_only: false,
        }
    }
}

impl RuleEdit {
    fn is_default(&self) -> bool {
        self.channel.is_none()
            && self.transpose == 0
            && self.key_lo == 0
            && self.key_hi == 127
            && self.vel_lo == 0
            && self.vel_hi == 127
            && self.enabled
            && self.cc_map.is_empty()
            && !self.cc_only
    }
    fn set_cc(&mut self, m: crate::matrix::CcMapping) {
        let m = crate::matrix::CcMapping { cc: m.cc & 0x7F, ..m };
        match self.cc_map.iter_mut().find(|x| x.cc == m.cc) {
            Some(x) => *x = m,
            None => self.cc_map.push(m),
        }
    }
    fn unmap_cc(&mut self, cc: u8) {
        let cc = cc & 0x7F;
        self.cc_map.retain(|m| m.cc != cc);
    }
    fn summary(&self) -> String {
        let mut parts: Vec<String> = Vec::new();
        if let Some(ch) = self.channel { parts.push(format!("ch {}", ch + 1)); }
        if self.transpose != 0 { parts.push(format!("{:+} st", self.transpose)); }
        if (self.key_lo, self.key_hi) != (0, 127) { parts.push(format!("keys {}–{}", self.key_lo, self.key_hi)); }
        if (self.vel_lo, self.vel_hi) != (0, 127) { parts.push(format!("vel {}–{}", self.vel_lo, self.vel_hi)); }
        if !self.cc_map.is_empty() { parts.push(format!("{} CC", self.cc_map.len())); }
        if !self.enabled { parts.push("muted".into()); }
        if parts.is_empty() { "transparent".into() } else { parts.join(" · ") }
    }
    /// In-cell code for a routed matrix cell: the rule's defining change,
    /// so a shaped route reads differently from a plain one at a glance.
    fn cell_code(&self) -> String {
        if !self.enabled { return "off".into(); }
        if self.transpose != 0 { return format!("{:+}", self.transpose); }
        if let Some(ch) = self.channel { return format!("ch {}", ch + 1); }
        if (self.key_lo, self.key_hi) != (0, 127) { return "keys".into(); }
        if (self.vel_lo, self.vel_hi) != (0, 127) { return "vel".into(); }
        if !self.cc_map.is_empty() { return format!("{} CC", self.cc_map.len()); }
        "ALL".into()
    }
    fn to_command(&self, source: SourceId, dest: u32) -> Command {
        Command::MatrixRule {
            source, dest,
            channel: self.channel,
            transpose: self.transpose,
            key_lo: self.key_lo, key_hi: self.key_hi,
            vel_lo: self.vel_lo, vel_hi: self.vel_hi,
            enabled: self.enabled,
        }
    }
}

/// How long MIDI learn keeps listening after the last CC event on the
/// captured controller so the player can move (e.g. bite and release) through
/// its full min..max before locking in the adapted curve.
const LEARN_SETTLE_SECS: f32 = 1.5;

/// Minimum CC travel (`max - min`) observed during MIDI learn before adapting
/// the input curve to `min..=max`. Keeps a single CC packet or 1–3 steps of
/// pot jitter on a normal 0..=127 knob from collapsing the range, while still
/// adapting narrow sensors like a wind controller's bite CC.
const LEARN_MIN_SPAN: u8 = 4;

#[derive(Clone, Debug, PartialEq)]
struct CcLearnCapture {
    source: SourceId,
    cc: u8,
    min: u8,
    max: u8,
    last_val: u8,
    /// `ui_time` of the most recent CC sample on this controller.
    last_at: f32,
}

impl CcLearnCapture {
    fn scale(&self) -> crate::matrix::CcScale {
        if self.max.saturating_sub(self.min) >= LEARN_MIN_SPAN {
            crate::matrix::CcScale::input_range(self.min, self.max)
        } else {
            crate::matrix::CcScale::IDENTITY
        }
    }

    fn tag(&self) -> String {
        if self.max > self.min {
            format!("CC {} · {}–{}", self.cc, self.min, self.max)
        } else {
            format!("CC {} · {}", self.cc, self.min)
        }
    }
}

/// An on/off CC destination (mixer Mute/Solo, sustain and soft pedals):
/// learn binds it on the first CC and it gets no range or curve.
fn cc_dest_is_switch(target: crate::matrix::CcTarget, param: u32) -> bool {
    (target == CcTarget::Mix && MixControl::from_param(param).is_some_and(|c| c.is_switch()))
        || (target == CcTarget::MidiCc && crate::matrix::midi_cc_is_switch(param))
}

#[derive(Clone, Debug, PartialEq)]
struct CcLearn {
    source: SourceId,
    dest: u32,
    param: u32,
    target: crate::matrix::CcTarget,
    /// When armed from a rack knob, replace any prior binding for that knob on completion.
    replace_existing: bool,
    /// Populated once the first matching CC arrives; tracks the min..=max
    /// values seen during learning until the controller settles.
    capture: Option<CcLearnCapture>,
}

impl CcLearn {
    fn new(
        source: SourceId,
        dest: u32,
        param: u32,
        target: crate::matrix::CcTarget,
        replace_existing: bool,
    ) -> Self {
        Self { source, dest, param, target, replace_existing, capture: None }
    }

    fn is_switch(&self) -> bool {
        cc_dest_is_switch(self.target, self.param)
    }

    fn capture_json(&self) -> Option<serde_json::Value> {
        self.capture.as_ref().map(|c| serde_json::json!({
            "cc": c.cc, "min": c.min, "max": c.max,
        }))
    }
}

/// The knob context menu, keyed by what the knob drives — never unit/knob
/// indices, which a rebuild can shift under an open menu (rule 10, #24).
/// A destructive tool the assistant asked about: what to run on Confirm.
