enum Drag {
    None,
    /// Incremental knob drag: `accum` tracks continuous travel (so stepped knobs
    /// and mid-drag Shift fine-tune toggles never jump), `last_y` is the previous
    /// frame's pointer y, and `fine` records whether Shift is currently held (#304).
    Knob { unit: usize, idx: usize, accum: f32, last_y: f32, fine: bool },
    /// Holding a plug: `id` is the cable id, `end` the held end.
    Plug { id: u32, end: Dir },
    Cable { id: u32, u: f32 },
    /// Ctrl+drag a rack unit to rearrange it (task-21). `grab` is the pointer's
    /// rack-local offset inside the unit at press, so the box tracks the cursor.
    Unit { unit: usize, grab: Vec2 },
    /// Dragging a Keys face's split-point readout: `cur` is the point last
    /// sent, shown while dragging (the engine publication lags a block).
    Split { unit: usize, start: u8, press: Pos2, cur: u8 },
    /// Dragging a metronome face's BPM readout (the one global tempo).
    Bpm { start: f32, press: Pos2 },
    /// Pulling one of an organ face's drawbars (`bar` 0 = 16').
    Drawbar { unit: usize, bar: usize },
}

/// Rack-local → screen transform for the flip (squash around the horizontal
/// axis). All rack drawing goes through this.
/// The rack's margins and spacing (points). A small window drops to `TIGHT`
/// before any face goes below its floor.
#[derive(Clone, Copy, Debug, PartialEq)]
struct RackChrome {
    /// Stage edge to the rack, each side.
    margin: f32,
    /// Stage top to the rack's view.
    top: f32,
    /// Room for the hint line under the rack.
    hint: f32,
    /// Rack edge to the units.
    pad: f32,
    /// Width of the side rails.
    rail: f32,
    /// Between units.
    gap: f32,
    /// Corner radius of the rack panel.
    radius: f32,
}

impl RackChrome {
    const ROOMY: Self = Self { margin: 30.0, top: 40.0, hint: 36.0, pad: 20.0, rail: 14.0, gap: 12.0, radius: 36.0 };
    const TIGHT: Self = Self { margin: 8.0, top: 8.0, hint: 30.0, pad: 10.0, rail: 8.0, gap: 8.0, radius: 22.0 };
}

/// Readable floors of a rack unit (points).
const MIN_UNIT_H: f32 = 136.0;
const FACE_MIN_W: f32 = 150.0;

#[derive(Clone, Copy)]
struct Xform {
    center: Pos2, // screen
    lc: Vec2,     // rack-local center
    sx: f32,
    sy: f32,
}

impl Xform {
    fn p(&self, l: Vec2) -> Pos2 {
        Pos2::new(
            self.center.x + (l.x - self.lc.x) * self.sx,
            self.center.y + (l.y - self.lc.y) * self.sy,
        )
    }
    fn rect(&self, r: Rect) -> Rect {
        Rect::from_min_max(self.p(r.min.to_vec2()), self.p(r.max.to_vec2()))
    }
    fn inv(&self, s: Pos2) -> Vec2 {
        Vec2::new(
            self.lc.x + (s.x - self.center.x) / self.sx,
            self.lc.y + (s.y - self.center.y) / self.sy,
        )
    }
}

// ---------------------------------------------------------------------------
// Agent activity tracking (rack / cable / matrix / assistant highlights)
// ---------------------------------------------------------------------------

/// Duration (seconds) an agent-touched unit/cable/cell remains highlighted
/// before fading completely away.
const AGENT_TOUCH_SECS: f32 = 2.6;
/// Fade-out tail (seconds) at the end of [`AGENT_TOUCH_SECS`].
const AGENT_FADE_SECS: f32 = 1.2;

/// One agent-undo step: everything a rig edit or session load restores
/// (graph + knobs + plugin states + matrix via the session, plus the rig
/// list, mixer, rig in view and patch names that the session does not carry).
struct UndoSnap {
    session: crate::session::Session,
    rigs: Vec<crate::control::RigMeta>,
    mix: [crate::engine::RigMix; crate::control::MAX_RIGS],
    arm_master: bool,
    arm_rigs: [bool; crate::control::MAX_RIGS],
    active: usize,
    /// Per-voice source switches, device and patch name (not in the session).
    voices: Vec<VoiceRow>,
}

/// One CLAP unit's entry of the per-voice slot tables (`rig_sources`,
/// `rig_device`, `patch_names`) under its node id: how the tables travel
/// across a reload that resets them (undo, rig edit).
#[derive(Clone)]
struct VoiceRow {
    node: u32,
    sources: (bool, bool),
    device: Option<u32>,
    patch_name: Option<String>,
}

/// A dB/LU value with a real minus sign and an explicit plus: "\u{2212}14", "+7.1".
fn signed_db(v: f32, decimals: usize) -> String {
    let body = format!("{:.*}", decimals, v.abs());
    if v < 0.0 && body.trim_matches(|c| c == '0' || c == '.') != "" { format!("\u{2212}{body}") }
    else if v > 0.0 { format!("+{body}") }
    else { body }
}

/// The text with its first letter in upper case (a status line as a message).
fn sentence_first(s: &str) -> String {
    let mut c = s.chars();
    c.next().map(|f| f.to_uppercase().collect::<String>() + c.as_str()).unwrap_or_default()
}

