    /// #163: each keyboard surface in AUTO on the rig it follows, with a
    /// held C major chord, plus the dual manual and the expanded view.
    #[test]
    #[ignore = "writes PNGs: KABELSALAT_SHOTS=<dir> cargo test --bin kabelsalat keyboard_surface_shots -- --ignored"]
    fn keyboard_surface_shots() {
        use crate::keyboard::KeyboardType;
        let dir = std::path::PathBuf::from(std::env::var("KABELSALAT_SHOTS").expect("KABELSALAT_SHOTS=<dir>"));
        std::fs::create_dir_all(&dir).unwrap();
        let rig = |app: &mut DemoApp, kind: NodeKind, name: &str| {
            let mut g = crate::control::Graph::default();
            let keys = g.add_node(NodeKind::Keys, name_bytes("KEYS"));
            let inst = g.add_node(kind, name_bytes(name));
            let master = g.add_node(NodeKind::MasterOut, name_bytes("MASTER"));
            g.connect_with_id(1, PortRef { node: keys, port: 0 }, PortRef { node: inst, port: 0 }, crate::control::PortKind::Midi);
            g.connect_with_id(2, PortRef { node: inst, port: 0 }, PortRef { node: master, port: 0 }, crate::control::PortKind::Audio);
            app.build_rack(&g, &[]);
        };
        let organ = || NodeKind::Lv2 { uri: Lv2Uri::new(crate::organ::B_SYNTH) };
        let aeolus = || NodeKind::Clap { plugin_id: crate::control::ClapId::new(crate::aeolus::AEOLUS_ID) };
        let mains = |a: &mut DemoApp| super::main_control_tests::give_clap_units_main_knobs(a);
        // A hosted Aeolus with piston 2 (Principal Chorus) drawn.
        let chorus = |a: &mut DemoApp| {
            if let Some(u) = a.kb_target_unit() {
                let node = a.units[u].node_id;
                let reg = crate::keyboard::pipe_piston_registration(1).unwrap();
                a.aeolus_faces.entry(node).or_default().drawn = crate::aeolus::drawn(&crate::aeolus::state(reg));
                a.aeolus_poll_at = a.ui_time + 1e6; // no live plugin to poll in a shot
            }
        };
        let clap = |id: &str| NodeKind::Clap { plugin_id: crate::control::ClapId::new(id) };
        let views: [(&str, &dyn Fn(&mut DemoApp)); 19] = [
            // #198 phase 1: the four new types, detected from their catalog
            // plugin and drawn with the interim surface.
            ("electric-piano", &|a| a.rig_types = vec![Some(KeyboardType::ElectricPiano)]),
            ("electric-piano-expanded", &|a| { a.rig_types = vec![Some(KeyboardType::ElectricPiano)]; a.kb_expanded = true }),
            // A bass plays in its own register: the held chord lands on the neck.
            ("bass", &|a| { rig(a, clap("com.punklabs.onetrick.chonk"), "CHONK"); mains(a); a.octave = 2 }),
            ("bass-expanded", &|a| { rig(a, clap("com.punklabs.onetrick.chonk"), "CHONK"); mains(a); a.octave = 2; a.kb_expanded = true }),
            ("wind", &|a| { rig(a, clap("org.starbreath.starbreath"), "STARBREATH"); mains(a) }),
            ("wind-expanded", &|a| { rig(a, clap("org.starbreath.starbreath"), "STARBREATH"); mains(a); a.kb_expanded = true }),
            ("drums", &|a| { rig(a, clap("com.punklabs.onetrick.cryptid"), "CRYPTID"); mains(a) }),
            ("drums-expanded", &|a| { rig(a, clap("com.punklabs.onetrick.cryptid"), "CRYPTID"); mains(a); a.kb_expanded = true }),
            ("synth", &|a| mains(a)),
            ("synth-expanded", &|a| { mains(a); a.kb_expanded = true }),
            ("jazz-organ-expanded", &|a| { rig(a, organ(), "ORGAN"); a.kb_expanded = true }),
            ("jazz-organ-dual-expanded", &|a| { rig(a, organ(), "ORGAN"); a.kb_dual_manual = true; a.kb_expanded = true }),
            ("piano", &|a| a.rig_types = vec![Some(KeyboardType::Piano)]),
            ("piano-expanded", &|a| { a.rig_types = vec![Some(KeyboardType::Piano)]; a.kb_expanded = true; a.kb_sustain = true }),
            ("jazz-organ", &|a| rig(a, organ(), "ORGAN")),
            ("jazz-organ-dual", &|a| { rig(a, organ(), "ORGAN"); a.kb_dual_manual = true }),
            ("pipe-organ", &|a| { rig(a, aeolus(), "AEOLUS"); chorus(a) }),
            ("pipe-organ-expanded", &|a| { rig(a, aeolus(), "AEOLUS"); chorus(a); a.kb_expanded = true }),
            ("pipe-organ-preview-expanded", &|a| { a.rig_types = vec![Some(KeyboardType::PipeOrgan)]; a.kb_expanded = true }),
        ];
        let only = std::env::var("KABELSALAT_SHOTS_ONLY").ok();
        // KABELSALAT_SHOTS_SIZES=781x950,1576x468 renders other window sizes.
        let sizes: Vec<(f32, f32)> = std::env::var("KABELSALAT_SHOTS_SIZES").ok()
            .map(|s| s.split(',').filter_map(|wh| { let (w, h) = wh.split_once('x')?; Some((w.parse().ok()?, h.parse().ok()?)) }).collect())
            .unwrap_or_else(|| vec![(1600.0, 1000.0), (1000.0, 700.0), (781.0, 468.0)]);
        for (w, h) in sizes {
            for (name, setup) in &views {
                if only.as_deref().is_some_and(|o| !name.contains(o)) { continue; }
                let mut app = DemoApp::new_with_sink(None); // rule 148: fresh per image
                setup(&mut app);
                app.dock = DockView::Keyboard;
                let base = 12 * (app.octave as usize + 1);
                for n in [base, base + 4, base + 7] {
                    app.note_leds[n] = 1.0;
                    app.notes_down[n] = 1;
                }
                shot(&mut app, Vec2::new(w, h), &dir.join(format!("{w}x{h}-kbd-{name}.png")));
            }
        }
    }

    /// Screenshots of the type-organized Plugins stage (All, Instruments,
    /// Effects with subcategories, MIDI FX, Utilities, Install) using the
    /// machine's real scanned CLAP + LV2 plugins.
    #[test]
    #[ignore = "writes PNGs: KABELSALAT_SHOTS=<dir> cargo test --bin kabelsalat plugin_categories_shots -- --ignored"]
    fn plugin_categories_shots() {
        let dir = std::path::PathBuf::from(std::env::var("KABELSALAT_SHOTS").expect("KABELSALAT_SHOTS=<dir>"));
        std::fs::create_dir_all(&dir).unwrap();
        let clap = crate::host::list_clap_plugins();
        let lv2 = crate::lv2::discover();
        let cases: &[(&str, PluginCategory, Option<PluginSubtype>, Vec2)] = &[
            ("1600x1000-all.png", PluginCategory::All, None, Vec2::new(1600.0, 1000.0)),
            ("1600x1000-instruments.png", PluginCategory::Instruments, None, Vec2::new(1600.0, 1000.0)),
            ("1600x1000-effects.png", PluginCategory::Effects, None, Vec2::new(1600.0, 1000.0)),
            ("1600x1000-effects-drive.png", PluginCategory::Effects, Some(PluginSubtype::DriveAmp), Vec2::new(1600.0, 1000.0)),
            ("1600x1000-midifx.png", PluginCategory::MidiFx, None, Vec2::new(1600.0, 1000.0)),
            ("1600x1000-utilities.png", PluginCategory::Utilities, None, Vec2::new(1600.0, 1000.0)),
            ("1600x1000-install.png", PluginCategory::Install, None, Vec2::new(1600.0, 1000.0)),
            ("781x950-effects.png", PluginCategory::Effects, None, Vec2::new(781.0, 950.0)),
            ("760x520-all.png", PluginCategory::All, None, Vec2::new(760.0, 520.0)),
        ];
        {
            let mut app = DemoApp::new_with_sink(None);
            app.plugins_loaded = true;
            app.plugins_lv2 = lv2.clone();
            app.stage_view = StageView::Mixer;
            let synth = app.units.iter().find(|u| matches!(u.node_kind, UnitKind::Clap)).unwrap().node_id;
            app.insert_pick = Some(Some(synth));
            app.insert_subtype = Some(PluginSubtype::Dynamics);
            shot(&mut app, Vec2::new(1600.0, 1000.0), &dir.join("1600x1000-insert-picker-dynamics.png"));
        }
        for (file, cat, sub, size) in cases {
            let mut app = DemoApp::new_with_sink(None);
            app.plugins_loaded = true;
            app.plugins_clap = clap.clone();
            app.plugins_lv2 = lv2.clone();
            app.stage_view = StageView::Plugins;
            app.plugin_category = *cat;
            app.plugin_subtype = *sub;
            shot(&mut app, *size, &dir.join(file));
        }
    }

    #[test]
    #[ignore = "writes PNGs: KABELSALAT_SHOTS=<dir> cargo test --bin kabelsalat window_size_shots -- --ignored"]
